mapper.select:
select *
from asset_residual_config
where standard_product_sku_id = #{skuId}
  and partner_id = #{partnerId}
  and is_deleted = 0
limit 1

mapper.delete:
delete from asset_residual_config
where standard_product_sku_id = #{skuId}
  and partner_id = #{partnerId}
  and is_deleted = 1

mapper.update:
update asset_residual_config
set is_deleted = 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
where standard_product_sku_id = #{skuId}
  and partner_id = #{partnerId}
  and is_deleted = 0
